var n=`0572-kazy-with-noodles`;var i=`world-0572`;var a=`KZ`;var o=`central-asia`;var s=4;var r=105;var l={en:`Kazy with Noodles`,ua:`Кази з локшиною`};var d={en:`A traditional dish from Kazakhstan, centered on horse meat, all-purpose flour, chicken egg, yellow onion. A measured home-kitchen version organized by cooking step. Kazy-inspired sliced boiled horse meat rather than genuine horse sausage; the catalog lacks prepared kazy and sausage casings.`,ua:`Традиційна страва кухні країни Казахстан. Основні складники: конина, пшеничне борошно універсальне, куряче яйце, жовта цибуля. Домашній варіант із кількостями продуктів за етапами приготування. Відварена нарізана конина у стилі кази замість справжньої ковбаси; готового кази й оболонок у каталозі немає.`};var g=[{en:`Simmer horse meat gently in salted water until safely cooked through; genuine kazy is a specific cured horse sausage, not reproduced here.`,ua:`Повільно відварюйте конину в підсоленій воді до повної готовності; справжній кази, окрема в’ялена кінська ковбаса, яку тут не відтворено.`,t:[`boiling`],m:70,i:[[`horse-meat`,400,`g`],[`water`,1200,`ml`]]},{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 15 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 15 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:15,i:[[`all-purpose-flour`,300,`g`],[`chicken-egg`,1,`pcs`],[`water`,120,`ml`]]},{en:`Add the listed ingredients to the pot. Keep at a gentle simmer for about 13 minutes, until tender and cooked through.`,ua:`Додайте зазначені складники до каструлі. Варіть за слабкого кипіння приблизно 13 хвилин до м’якості та готовності.`,t:[`simmering`],m:13,i:[]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:7,i:[[`yellow-onion`,190,`g`],[`ground-black-pepper`,null,`to_taste`]]}];var h={slug:n,id:i,country:`KZ`,region:o,servings:4,minutes:105,title:l,text:d,steps:g};export{a as country,h as default,i as id,r as minutes,o as region,s as servings,n as slug,g as steps,d as text,l as title};